function projectViewBase(){const derived=['JOB_ID','DATE_OPENED','CURRENT_ITERATION','CURRENT_STAGE','CURRENT_STATE','CURRENT_INPUT_VERSION','CURRENT_SOURCE_SET_VERSION','CURRENT_REQUIREMENTS_VERSION','CURRENT_TEST_SUITE_VERSION','CURRENT_INSTRUCTION_VERSION','CURRENT_BASELINE_ID','CURRENT_PRODUCT_ID','CURRENT_BLOCKERS','NEXT_REQUIRED_ACTION','LATEST_EVIDENCE_REFERENCE'];return `<div class="panel"><h2 class="section-title">Project information</h2><p class="section-intro">Enter only genuine human-owned User Job Input. The source count is a search target, not a quota and never permission to invent weaker sources. You do not need to know the final file format in advance: Stage 01 determines the actual artifact set and suitable formats. If the chosen agent can reliably construct the requested file or package from a defined representation and sufficient inputs, it should produce that real artifact even when a downstream authoring, build, CAD/CAM, filing, manufacturing, or other consuming system is unavailable. Opening, importing, building, executing, manufacturing, filing, or testing remains separately verified. A specification substitute requires human confirmation and is used only when the requested actual artifact cannot be generated reliably. This static application does not itself access external repositories, websites, or accounts; those capabilities depend on the external agent context you choose to run. The application derives workflow identity, versions, status, counts, and next action.</p><div class="grid-2">${jobFields.map(([k,l,t])=>`<div class="field${t==='textarea'?' full':''}"><label>${l}</label>${t==='textarea'?`<textarea data-job="${k}">${esc(current.job[k]||'')}</textarea>`:`<input data-job="${k}" type="${t==='number'?'number':'text'}"${t==='number'?' min="0" step="1" inputmode="numeric" placeholder="Leave blank if unknown"':''} value="${esc(current.job[k]??'')}">`}${t==='number'?'<span class="help">Whole number only. Leave blank if unknown or no preference.</span>':''}</div>`).join('')}</div><div class="button-row"><button class="primary" id="save-job">Save User Job Input</button></div></div><div class="panel"><h2 class="section-title">Application-derived job control</h2>${details('Current derived values',Object.fromEntries(derived.map(k=>[k,current.job[k]])),true)}</div>${Object.keys(current.projectData.userEntered||{}).length?`<div class="panel"><h2 class="section-title">Original project input</h2>${details('User-entered data',current.projectData.userEntered,true)}</div>`:''}`;}
function projectDeletionMarkup(){
  const jobId=String(current?.job?.JOB_ID||'').trim();
  if(!jobId)return '';
  if(current?.isRetainedTestProject)return `<details class="record-card" id="project-management"><summary>Project management<span>Advanced</span></summary><div class="record-body"><div class="notice">This built-in retained reference project is restored by the application and cannot be permanently deleted. Select a normal project to use project deletion.</div></div></details>`;
  return `<details class="record-card" id="project-management"><summary>Project management<span>Advanced</span></summary><div class="record-body"><div class="notice danger"><strong>Permanent deletion.</strong><br>This removes this project and every artifact byte stored for it from this browser. Export a backup first if you may need it later.</div><div class="field"><label for="delete-project-confirmation">Type the exact JOB_ID to enable deletion</label><input id="delete-project-confirmation" autocomplete="off" autocorrect="off" autocapitalize="none" spellcheck="false" placeholder="${esc(jobId)}" aria-describedby="delete-project-confirmation-help"><span class="help" id="delete-project-confirmation-help">Required: ${esc(jobId)}</span></div><div class="button-row"><button class="danger" id="delete-project" type="button" disabled>Permanently delete project</button></div></div></details>`;
}
