function humanStageMarkup(n,locked){if(n===1){if(current.isRetainedTestProject&&current.stages[1].status==='COMPLETE')return `<div class="notice success">Stage 01 is preserved completed history for this retained project. No historical event has been fabricated or rewritten.</div>`;return `<div class="panel"><h2 class="section-title">Human job intake</h2><p class="section-intro">Stage 01 is an intake conversation. Save any facts you already know here, then send the generated instruction to ChatGPT. The agent should use supplied files and ask only the remaining human-only questions in normal chat. Stay in ChatGPT until it returns the final JSON. HUMAN_INPUT_REQUIRED in this app is only a fallback when a required answer remains unavailable or deferred, or interactive conversation was unavailable.</p><div class="button-row"><button data-view="Project">Open User Job Input</button></div></div>`;}const fields=schema.humanStageFields(n);if(!fields.length)return '';const data=current.stages[n].humanData||{};return `<div class="panel"><h2 class="section-title">Human-owned stage input</h2><div class="grid-2">${fields.map(name=>`<div class="field"><label>${esc(label(name))}</label><input data-human-stage-field="${esc(name)}" value="${esc(data[name]||'')}"${locked?' disabled':''}></div>`).join('')}</div><div class="button-row"><button id="save-human-stage"${locked?' disabled':''}>Save human decision/input</button></div></div>`;}
