async function saveJob(){const sourceCountInput=document.querySelector('[data-job="DESIRED_SOURCE_COUNT"]');if(sourceCountInput){sourceCountInput.setCustomValidity('');const raw=sourceCountInput.value.trim(),numeric=Number(raw);if(raw!==''&&(!/^\d+$/.test(raw)||!Number.isSafeInteger(numeric))){sourceCountInput.setCustomValidity('Enter a whole number of 0 or more, or leave this field blank.');sourceCountInput.focus();sourceCountInput.reportValidity();announce('source count must be a whole number or blank');return;}}const next=clone(current),changed=[];document.querySelectorAll('[data-job]').forEach(x=>{const key=x.dataset.job,value=x.type==='number'?(x.value===''?null:Number(x.value)):x.value;if(next.job[key]!==value){next.job[key]=value;changed.push(key);}});if(!changed.length)return render();next.projectData.userEntered={...next.projectData.userEntered,objective:next.job.EXACT_USER_OBJECTIVE_VERBATIM,suppliedMaterials:next.job.SUPPLIED_MATERIALS_INVENTORY,requiredOutputFormat:next.job.REQUIRED_OUTPUT_FORMAT,deadlineOrTemporalScope:next.job.DEADLINE_OR_TEMPORAL_SCOPE,desiredSourceCount:next.job.DESIRED_SOURCE_COUNT,knownAuthorities:next.job.KNOWN_AUTHORITATIVE_SOURCES,availableTools:next.job.AVAILABLE_TOOLS,prohibitedActions:next.job.PROHIBITED_ACTIONS,explicitRequirements:String(next.job.EXPLICIT_USER_REQUIREMENTS||'').split(/\r?\n/).filter(Boolean)};engine.recordHumanInputVersion(next,changed,'HUMAN_OPERATOR');if(next.stages[1].status==='COMPLETE'&&!next.isRetainedTestProject)engine.invalidateStageForAuthorityChange(next,{stage:1,reason:'User Job Input changed after Stage 01 completion.',operatorLabel:'HUMAN_OPERATOR'});await persistReplacement(next);render();}
