  const n=current.activeStage,text=$('#stage-output')?.value||'',prompt=responsePromptRecord(n,text);if(!prompt){alert('No saved instruction matches this response. Save and copy the current instruction, run that exact instruction in ChatGPT, then paste its final JSON here. Parse / validate does not create a new instruction.');return;}let captured;
