async function storeArtifactFile(file,stage=current.activeStage,lineage={}){const artifactId=artifactIdFor(),filename=logicalFilePath(file),blob=file.slice(0,file.size,file.type||'application/octet-stream'),stored=await projectStore.putArtifact({artifactId,jobId:current.job.JOB_ID,blob,filename,mediaType:file.type||'application/octet-stream',lineage:{stage,role:core.STAGES[stage-1]?.role||'UNKNOWN',logicalPath:filename,...lineage}});return {stored,view:{artifactId,name:stored.filename,type:stored.mediaType,size:stored.byteSize,sha256:stored.sha256,stage:`STAGE ${String(stage).padStart(2,'0')}`,role:core.STAGES[stage-1]?.role||'UNKNOWN',retainedBytes:true,availability:'IndexedDB Blob bytes persisted and rehashed on read-back.',addedAt:new Date().toISOString()}};}
async function registerStageFiles(fileList){const stage=current.activeStage,created=[];try{const product=stage===21?currentStageProduct():null;if(stage===21&&!product)throw new Error('Reserve the current Stage 21 product execution before selecting finished-product files.');const productId=product?engine.recordId(product,'products'):null,paths=fileList.map(logicalFilePath);if(new Set(paths).size!==paths.length)throw new Error('Selected artifact package contains duplicate logical paths. Use the folder picker for structured packages so directory identity is preserved.');for(const file of fileList)created.push(await storeArtifactFile(file,stage,productId?{productId}:{}));const next=clone(current);for(const item of created){const stored=item.stored;engine.registerArtifactBytes(next,{stage,artifactId:stored.artifactId,filename:stored.filename,mediaType:stored.mediaType,byteSize:stored.byteSize,sha256:stored.sha256,lineage:stored.lineage});next.stages[stage].authorizedFiles.push(item.view);}await persistReplacement(next);announce('artifact bytes saved and verified');render();}catch(error){for(const item of created)try{await projectStore.deleteArtifact?.(item.stored.artifactId,current.job.JOB_ID);}catch{}announce('storage failed');alert(`Artifact storage failed without authorizing metadata-only state: ${error.message||error}`);}}
